func (t Event) ValueByDiscriminator() (interface{}, error) {
	discriminator, err := t.Discriminator()
	if err != nil {
		return nil, err
	}
	switch discriminator {
	case "approval.updated":
		return t.AsApprovalUpdatedEvent()
	case "deployment.updated":
		return t.AsDeploymentUpdatedEvent()
	case "heartbeat":
		return t.AsControlEvent()
	case "notification":
		return t.AsNotificationEvent()
	case "request.log":
		return t.AsRequestLogEvent()
	case "request.step":
		return t.AsRequestStepEvent()
	case "request.updated":
		return t.AsRequestUpdatedEvent()
	case "resource.updated":
		return t.AsResourceUpdatedEvent()
	case "resync":
		return t.AsControlEvent()
	default:
		return nil, errors.New("unknown discriminator value: " + discriminator)
	}
}

